#!/usr/bin/env bash
# Root-only, one-time installer for nfelo.github.io.
# Upload this single file to the repository root, open a GitHub Codespace, and
# run: bash install-global-club-rankings.sh

set -Eeuo pipefail

installer="install-global-club-rankings.sh"
patch_base="e0aa0079cde39016158def9c77375be920676a8e"
compressed_sha="95e2bcb7713fc6ca52c8e4b021121959d4d3115ec29513a05a72a61528a025af"
patch_sha="ed15597b9a3768dac6c6d0de6b40b0cae42d90224152562096b9a708c91b1de9"

fail() {
  printf 'ERROR: %s\n' "$*" >&2
  exit 1
}

command -v git >/dev/null 2>&1 || fail "git is required."
command -v base64 >/dev/null 2>&1 || fail "base64 is required."
command -v gzip >/dev/null 2>&1 || fail "gzip is required."

repo_root="$(git rev-parse --show-toplevel 2>/dev/null)" || fail "Run this inside the nfelo.github.io repository."
cd "$repo_root"

[ -f "$installer" ] || fail "Place $installer in the repository root without renaming it."
git ls-files --error-unmatch "$installer" >/dev/null 2>&1 || fail "Commit and push $installer before running it."
[ "$(git branch --show-current)" = "main" ] || fail "Run this from the main branch."

if ! git diff --quiet || ! git diff --cached --quiet || [ -n "$(git ls-files --others --exclude-standard)" ]; then
  fail "The working tree must be clean before installation."
fi

printf 'Checking main and the audited base revision...\n'
git fetch --no-tags origin main
[ "$(git rev-parse HEAD)" = "$(git rev-parse origin/main)" ] || fail "Local main is not current. Update the Codespace and run again."
git merge-base --is-ancestor "$patch_base" HEAD || fail "main does not contain audited base revision $patch_base."

temporary_parent="${TMPDIR:-/tmp}"
if [ ! -d "$temporary_parent" ]; then
  temporary_parent="$repo_root"
fi
temporary_dir="$(mktemp -d "$temporary_parent/.nfelo-club-install.XXXXXX")"
payload_gz="$temporary_dir/global-club-rankings.patch.gz"
patch_file="$temporary_dir/global-club-rankings.patch"
cleanup() {
  if [ -d "$temporary_dir" ]; then
    find "$temporary_dir" -type f -delete
    rmdir "$temporary_dir"
  fi
}
trap cleanup EXIT

printf 'Decoding and verifying the embedded installation payload...\n'
