GaoXIgA=
PATCH_PAYLOAD

echo "$compressed_sha  $payload_gz" | sha256sum --check --strict
gzip --decompress --stdout "$payload_gz" > "$patch_file"
echo "$patch_sha  $patch_file" | sha256sum --check --strict

printf 'Applying the audited club-ranking update...\n'
git apply --check --binary "$patch_file"
git apply --index --binary "$patch_file"
git diff --cached --check
changed_files="$temporary_dir/changed-files.txt"
git diff --cached --name-only > "$changed_files"

changed_count="$(wc -l < "$changed_files")"
[ "$changed_count" -eq 299 ] || fail "Expected 299 audited files, found $changed_count."
if grep -q '^\.github/workflows/' "$changed_files"; then
  fail "The application patch unexpectedly modifies a permanent workflow."
fi

if command -v node >/dev/null 2>&1; then
  node --check public/assets/app.js
  node --check public/clubs/clubs.js
fi

printf 'Removing the one-time installer and preparing the installation commit...\n'
git rm -- "$installer"
git diff --cached --quiet HEAD -- .github/workflows/pages.yml || fail "Refusing to modify pages.yml."
git diff --cached --check

if ! git config user.name >/dev/null; then
  git config user.name "nfelo installer"
fi
if ! git config user.email >/dev/null; then
  git config user.email "nfelo-installer@users.noreply.github.com"
fi

git commit -m "feat: add global club rankings"
git push origin HEAD:main

printf '\nGlobal club rankings installed and pushed.\n'
printf 'The existing Pages workflow has been triggered and will rebuild and test the complete site before deployment.\n'
